/// <summary>
/// PricingAttribute of table <c>WHSInventTable</c> field MaxPickQty.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeWHSInventTableMaxPickQty extends UPSPricingAttributeWHSInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(WHSInventTable, MaxPickQty);
}

public Set getAllowedValues()
{
    var            ret = new Set(Types::Real);
    WHSInventTable wHSInventTable;

    while select wHSInventTable
        group by MaxPickQty
    {
        if (! ret.in(wHSInventTable.MaxPickQty))
        {
            ret.add(wHSInventTable.MaxPickQty);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(WHSInventTable, MaxPickQty));
    qbr.value(queryValue(_value));
}
